// SPDX-License-Identifier: Apache-2.0
// Line-for-line port of core-engine/src/main/java/dev/fonebrew/domain/diff/LineDiff.kt
// (whole-line LCS with common prefix/suffix trimmed, hunks merged by context, git-style ranges).
// The Kotlin file is the truth: tests/linediff.test.cjs requires this port to reproduce
// golden/linediff.v1.json (generated by Kotlin, see LineDiffGoldenTest) byte for byte.
// No network, no storage, no DOM: pure functions.
(function (root) {
  "use strict";
  var MAX_CELLS = 8000000;

  function splitLines(s) {
    if (s.length === 0) return [];
    var parts = s.split("\n");
    return parts[parts.length - 1] === "" ? parts.slice(0, parts.length - 1) : parts;
  }

  function op(kind, text, oldIdx, newIdx) { return { kind: kind, text: text, oldIdx: oldIdx, newIdx: newIdx }; }
  // kind: " " context, "+" add, "-" remove

  function lcs(a, b, off) {
    var n = a.length, m = b.length, out = [], i, j;
    if (n === 0 && m === 0) return out;
    if (n === 0) { for (j = 0; j < m; j++) out.push(op("+", b[j], -1, off + j)); return out; }
    if (m === 0) { for (i = 0; i < n; i++) out.push(op("-", a[i], off + i, -1)); return out; }
    if (n * m > MAX_CELLS) {
      for (i = 0; i < n; i++) out.push(op("-", a[i], off + i, -1));
      for (j = 0; j < m; j++) out.push(op("+", b[j], -1, off + j));
      return out;
    }
    var dp = new Array(n + 1);
    for (i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1);
    for (i = n - 1; i >= 0; i--) {
      for (j = m - 1; j >= 0; j--) {
        dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
      }
    }
    i = 0; j = 0;
    while (i < n && j < m) {
      if (a[i] === b[j]) { out.push(op(" ", a[i], off + i, off + j)); i++; j++; }
      else if (dp[i + 1][j] >= dp[i][j + 1]) { out.push(op("-", a[i], off + i, -1)); i++; }
      else { out.push(op("+", b[j], -1, off + j)); j++; }
    }
    while (i < n) { out.push(op("-", a[i], off + i, -1)); i++; }
    while (j < m) { out.push(op("+", b[j], -1, off + j)); j++; }
    return out;
  }

  function align(a, b) {
    var p = 0, s = 0, k, out = [];
    while (p < a.length && p < b.length && a[p] === b[p]) p++;
    while (s < a.length - p && s < b.length - p && a[a.length - 1 - s] === b[b.length - 1 - s]) s++;
    for (k = 0; k < p; k++) out.push(op(" ", a[k], k, k));
    out = out.concat(lcs(a.slice(p, a.length - s), b.slice(p, b.length - s), p));
    for (k = 0; k < s; k++) {
      var oi = a.length - s + k, ni = b.length - s + k;
      out.push(op(" ", a[oi], oi, ni));
    }
    return out;
  }

  function toHunk(ops, lo, hi) {
    var slice = ops.slice(lo, hi + 1), oldStart = 0, newStart = 0, oldCount = 0, newCount = 0, k;
    for (k = 0; k < slice.length; k++) { if (slice[k].oldIdx >= 0) { oldStart = slice[k].oldIdx + 1; break; } }
    for (k = 0; k < slice.length; k++) { if (slice[k].newIdx >= 0) { newStart = slice[k].newIdx + 1; break; } }
    for (k = 0; k < slice.length; k++) { if (slice[k].oldIdx >= 0) oldCount++; if (slice[k].newIdx >= 0) newCount++; }
    return {
      oldStart: oldStart, oldCount: oldCount, newStart: newStart, newCount: newCount,
      lines: slice.map(function (o) { return [o.kind, o.text]; })
    };
  }

  function hunksOf(ops, context) {
    var n = ops.length, intervals = [], c;
    for (c = 0; c < n; c++) {
      if (ops[c].kind === " ") continue;
      var lo = Math.max(0, c - context), hi = Math.min(n - 1, c + context);
      var last = intervals.length ? intervals[intervals.length - 1] : null;
      if (last && lo <= last[1] + 1) last[1] = Math.max(last[1], hi);
      else intervals.push([lo, hi]);
    }
    return intervals.map(function (iv) { return toHunk(ops, iv[0], iv[1]); });
  }

  function diff(oldText, newText, context) {
    if (context === undefined) context = 3;
    return hunksOf(align(splitLines(oldText), splitLines(newText)), Math.max(0, context));
  }

  function stat(oldText, newText) {
    var added = 0, removed = 0, ops = align(splitLines(oldText), splitLines(newText));
    for (var k = 0; k < ops.length; k++) { if (ops[k].kind === "+") added++; else if (ops[k].kind === "-") removed++; }
    return { added: added, removed: removed };
  }

  function range(start, count) { return count === 1 ? String(start) : start + "," + count; }

  function unified(oldText, newText, oldPath, newPath, context) {
    if (oldPath === undefined) oldPath = "a";
    if (newPath === undefined) newPath = "b";
    var hunks = diff(oldText, newText, context);
    if (hunks.length === 0) return "";
    var s = "--- " + oldPath + "\n+++ " + newPath + "\n";
    hunks.forEach(function (h) {
      s += "@@ -" + range(h.oldStart, h.oldCount) + " +" + range(h.newStart, h.newCount) + " @@\n";
      h.lines.forEach(function (l) { s += l[0] + l[1] + "\n"; });
    });
    return s;
  }

  var api = { diff: diff, stat: stat, unified: unified };
  if (typeof module !== "undefined" && module.exports) module.exports = api;
  else root.FonebrewLineDiff = api;
})(typeof globalThis !== "undefined" ? globalThis : this);
